import 'package:flutter_test/flutter_test.dart';
import 'package:route_monitor/checkin/qr_verifier.dart';

// Values generated by the backend (Task 7) with the test key "11"*32 and
// floor_id=00000000-0000-0000-0000-000000000001 — the format is always
// "v1.<floor_id>.<version>.<sig>".
const _publicKeyHex =
    'd04ab232742bb4ab3a1368bd4615e4e6d0224ab71a016baf8520a332c9778737';
const _validPayload =
    'v1.00000000-0000-0000-0000-000000000001.1.'
    'M2wGfprp0zqRRCiAH6VNpSWYftIdtPiCaTBdmfNPtYtX'
    'cf2NmRKTFA-valGS9ElgvVyM4efOZ2rUnOjgMPyvCw==';

void main() {
  final verifier = QrVerifier(_publicKeyHex);

  test('verify accepts a payload signed by the matching private key', () async {
    final payload = await verifier.verify(_validPayload);

    expect(payload, isNotNull);
    expect(payload!.version, 1);
  });

  test('verify rejects a payload with a tampered floor_id', () async {
    final parts = _validPayload.split('.');
    final tampered =
        'v1.00000000-0000-0000-0000-000000000099.${parts[2]}.${parts[3]}';

    final payload = await verifier.verify(tampered);

    expect(payload, isNull);
  });

  test('verify rejects malformed input', () async {
    expect(await verifier.verify('not-a-qr-payload'), isNull);
    expect(await verifier.verify('v2.abc.1.sig'), isNull);
  });

  test(
    'verify rejects a well-formed-base64 signature of the wrong length '
    'instead of throwing',
    () async {
      // Regression: the cryptography package throws (not "returns false")
      // when the decoded signature isn't exactly 64 bytes — 'aaaa' decodes
      // to 3 bytes. An attacker- or typo-controlled QR sticker must never
      // crash the scanner (RF29, RNF13).
      expect(
        await verifier.verify('v1.abc.1.aaaa'),
        isNull,
      );
      expect(await verifier.verify('v1.abc.1.'), isNull);
    },
  );
}
